<?php
require_once dirname(__DIR__,2).'/core/bootstrap.php'; Auth::requireLogin(); $db=Database::getInstance()->pdo();
if($_SERVER['REQUEST_METHOD']==='POST'){
 Csrf::verify(isset($_POST['csrf_token'])?$_POST['csrf_token']:'');
 $customerId=(int)$_POST['customer_id']; $paid=max(0,(float)$_POST['paid']); $redeem=max(0,(int)$_POST['redeem']); $items=array(); $subtotal=0;
 foreach((isset($_POST['qty'])?$_POST['qty']:array()) as $pid=>$qty){$qty=(float)$qty;if($qty<=0)continue;$st=$db->prepare('SELECT id,name,cost,price FROM products WHERE id=? AND active=1');$st->execute(array((int)$pid));$p=$st->fetch();if($p){$items[]=array('p'=>$p,'qty'=>$qty);$subtotal+=(float)$p['price']*$qty;}}
 if(!$items){Helper::flash('اختار منتجاً واحداً على الأقل.','danger');Helper::redirect('modules/sales/pos.php');}
 try{$db->beginTransaction();$customer=null;$tier=null;
 if($customerId){$st=$db->prepare('SELECT c.*,t.discount_percent,t.point_value,t.first_order_points,t.order_threshold,t.threshold_points FROM customers c LEFT JOIN customer_tiers t ON t.id=c.tier_id WHERE c.id=? FOR UPDATE');$st->execute(array($customerId));$customer=$st->fetch();if(!$customer)throw new Exception('الزبون غير موجود.');}
  $tierDiscount=$customer?round($subtotal*(float)$customer['discount_percent']/100,2):0;$pointValue=$customer&&$customer['point_value']?(float)$customer['point_value']:0.1;if(!$customer)$redeem=0;$redeemValue=min(max(0,$subtotal-$tierDiscount),$redeem*$pointValue);if($customer&&$redeem>(int)$customer['points'])throw new Exception('رصيد النقاط غير كافٍ.');
 $total=max(0,round($subtotal-$tierDiscount-$redeemValue,2));if($paid>$total&& !$customer)$paid=$total;
 $invoice='CF-'.date('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,6));
 $st=$db->prepare('INSERT INTO sales(invoice_no,customer_id,user_id,subtotal,discount,total,paid,points_redeemed,created_at) VALUES(?,?,?,?,?,?,?,?,NOW())');$st->execute(array($invoice,$customerId?:null,Auth::user()['id'],$subtotal,$tierDiscount+$redeemValue,$total,$paid,$redeem));$saleId=$db->lastInsertId();
 $ins=$db->prepare('INSERT INTO sale_items(sale_id,product_id,product_name,quantity,unit_price,unit_cost) VALUES(?,?,?,?,?,?)');foreach($items as $it)$ins->execute(array($saleId,$it['p']['id'],$it['p']['name'],$it['qty'],$it['p']['price'],$it['p']['cost']));
 if($customer){$newBalance=round((float)$customer['balance']+$paid-$total,2);$newPoints=(int)$customer['points']-$redeem;$date=date('Y-m-d');$st=$db->prepare('SELECT order_count FROM daily_customer_orders WHERE customer_id=? AND order_date=? FOR UPDATE');$st->execute(array($customerId,$date));$orders=$st->fetchColumn();$orders=(int)$orders+1;$earned=($orders===1?(int)$customer['first_order_points']:0)+(((int)$customer['order_threshold']>0&&$orders%(int)$customer['order_threshold']===0)?(int)$customer['threshold_points']:0);$newPoints+=$earned;
 $db->prepare('INSERT INTO daily_customer_orders(customer_id,order_date,order_count) VALUES(?,?,1) ON DUPLICATE KEY UPDATE order_count=order_count+1')->execute(array($customerId,$date));$db->prepare('UPDATE customers SET balance=?,points=?,total_purchases=total_purchases+? WHERE id=?')->execute(array($newBalance,$newPoints,$total,$customerId));$db->prepare('UPDATE sales SET points_earned=? WHERE id=?')->execute(array($earned,$saleId));
 if($redeem)$db->prepare("INSERT INTO loyalty_points(customer_id,sale_id,type,points,balance_after,note,created_at) VALUES(?,?,'redeemed',?,?,?,NOW())")->execute(array($customerId,$saleId,-$redeem,$newPoints,'استبدال نقاط في فاتورة '.$invoice));if($earned)$db->prepare("INSERT INTO loyalty_points(customer_id,sale_id,type,points,balance_after,note,created_at) VALUES(?,?,'earned',?,?,?,NOW())")->execute(array($customerId,$saleId,$earned,$newPoints,'نقاط فاتورة '.$invoice));
 if($paid!=$total){$amount=round($paid-$total,2);$type=$amount>=0?'deposit':'debt_payment';$db->prepare('INSERT INTO payments(customer_id,user_id,type,amount,balance_after,note,created_at) VALUES(?,?,?,?,?,?,NOW())')->execute(array($customerId,Auth::user()['id'],$type,$amount,$newBalance,'تسوية فاتورة '.$invoice));}}
 $db->commit();Helper::redirect('modules/sales/receipt.php?id='.$saleId);
 }catch(Exception $e){if($db->inTransaction())$db->rollBack();Helper::flash($e->getMessage(),'danger');Helper::redirect('modules/sales/pos.php');}
}
$products=$db->query('SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.active=1 ORDER BY c.name,p.name')->fetchAll();$customers=$db->query('SELECT id,name,phone,points FROM customers ORDER BY name')->fetchAll();$pageTitle='نقطة البيع';require APP_ROOT.'/includes/header.php';
?><div class="page-heading"><div><h1>نقطة البيع</h1><p>حدد الكميات وسجل عملية البيع</p></div><a class="btn btn-outline-secondary" href="<?= APP_URL ?>/modules/sales/index.php">سجل المبيعات</a></div><form method="post" id="posForm"><?= Helper::csrfField() ?><div class="row g-3"><div class="col-lg-8"><div class="card"><div class="card-header">المنتجات</div><div class="card-body"><div class="row g-3"><?php foreach($products as $p): ?><div class="col-sm-6 col-xl-4"><div class="pos-product"><strong><?= Helper::e($p['name']) ?></strong><small class="muted"><?= Helper::e($p['category']) ?></small><div class="d-flex align-items-center justify-content-between mt-2"><span><?= Helper::money($p['price']) ?></span><input aria-label="الكمية" type="number" min="0" step="1" value="0" name="qty[<?= (int)$p['id'] ?>]" class="form-control form-control-sm qty-input" style="width:76px"></div></div></div><?php endforeach; ?><?php if(!$products): ?><p class="empty-state">أضف المنتجات أولاً.</p><?php endif; ?></div></div></div></div><div class="col-lg-4"><div class="card pos-cart"><div class="card-header">تفاصيل الأداء</div><div class="card-body"><label class="form-label">الزبون (اختياري)</label><select class="form-select mb-3" name="customer_id"><option value="0">زبون عابر</option><?php foreach($customers as $c): ?><option value="<?= (int)$c['id'] ?>"><?= Helper::e($c['name']) ?> · <?= (int)$c['points'] ?> نقطة</option><?php endforeach; ?></select><label class="form-label">النقاط المستبدلة</label><input class="form-control mb-3" type="number" name="redeem" min="0" value="0"><label class="form-label">المبلغ المدفوع</label><input class="form-control mb-3" type="number" name="paid" min="0" step="0.01" value="0" required><div class="alert alert-light">الإجمالي قبل الخصم: <strong id="posTotal">0.00 د.م</strong></div><button class="btn btn-coffee w-100" onclick="return confirm('تأكيد حفظ عملية البيع؟')"><i class="bi bi-check2-circle"></i> إتمام البيع</button></div></div></div></div></form><script>var posProducts=<?= json_encode(array_column($products,'price','id'),JSON_UNESCAPED_UNICODE) ?>;document.querySelectorAll('.qty-input').forEach(function(el){el.addEventListener('input',sumPos)});function sumPos(){var total=0;document.querySelectorAll('.qty-input').forEach(function(el){total+=(parseFloat(el.value)||0)*(parseFloat(posProducts[el.name.match(/\d+/)[0]])||0)});document.getElementById('posTotal').textContent=total.toFixed(2)+' د.م';}sumPos();</script><?php require APP_ROOT.'/includes/footer.php';
